3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.AgeBand;
8	import org.springframework.samples.petclinic.model.CheckDigit;
9	import org.springframework.samples.petclinic.model.CustomerCode;
10	import org.springframework.samples.petclinic.model.FiscalYear;
11	import org.springframework.samples.petclinic.model.Locality;
12	import org.springframework.samples.petclinic.model.Owner;
13	import org.springframework.samples.petclinic.model.OwnerIdentity;
14	import org.springframework.samples.petclinic.model.Tenure;
15	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
16	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
17	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
18	import org.springframework.samples.petclinic.rest.function.owner.OwnerTelephones;
19	
20	import java.util.Collection;
21	import java.util.List;
22	
23	/**
24	 * Maps Owner & OwnerDto using Mapstruct
25	 */
26	@Mapper(uses = PetMapper.class)
27	public interface OwnerMapper {
28	
29	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
30	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
31	    @Mapping(target = "initials", expression = "java(initials(owner))")
32	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
33	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
34	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
35	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
36	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
37	    @Mapping(target = "locality", expression = "java(locality(owner))")
38	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
39	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
40	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
41	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
42	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
43	    @Mapping(target = "possibleDuplicate", expression = "java(possibleDuplicate(owner))")
44	    OwnerDto toOwnerDto(Owner owner);
45	
46	    Owner toOwner(OwnerDto ownerDto);
47	
48	    /** The owner's salutation: '&lt;title&gt; &lt;lastName&gt;' when a title was supplied,
49	     * otherwise just the last name. */
50	    default String salutation(Owner owner) {
51	        String title = owner.getTitle();
52	        return (title == null || title.isBlank()) ? owner.getLastName() : title + " " + owner.getLastName();
53	    }
54	
55	    /** Format an owner's name as 'LastName, FirstName' for display. */
56	    default String displayName(Owner owner) {
57	        return owner.getLastName() + ", " + owner.getFirstName();
58	    }
59	
60	    /** The upper-cased first letters of firstName and lastName, dot-separated with a trailing dot. */
61	    default String initials(Owner owner) {
62	        return initial(owner.getFirstName()) + initial(owner.getLastName());
63	    }
64	
65	    /** The stored E.164 telephone formatted for humans (see {@link OwnerTelephones#toDisplay}). */
66	    default String telephoneDisplay(Owner owner) {
67	        return OwnerTelephones.toDisplay(owner.getTelephone());
68	    }
69	
70	    private static String initial(String name) {
71	        return Character.toUpperCase(name.charAt(0)) + ".";
72	    }
73	
74	    /** The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is the
75	     * last two digits of the fiscal year of the registrationDate (see {@link FiscalYear}). */
76	    default String membershipNumber(Owner owner) {
77	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
78	            return null;
79	        }
80	        return String.format("%s-M%02d", owner.getCustomerCode(), FiscalYear.of(owner.getRegistrationDate()) % 100);
81	    }
82	
83	    /** The owner's 'FY&lt;YY&gt;' fiscal year, derived from the business-day-adjusted
84	     * registrationDate (see {@link FiscalYear}), or null when the date is unknown. */
85	    default String fiscalYear(Owner owner) {
86	        return FiscalYear.label(owner.getRegistrationDate());
87	    }
88	
89	    /** The owner's membership points: starts at 0, plus 2 when an email is present, plus 1 when
90	     * namesakeCount is 0, plus 2 for a household of 3 or more, plus 3 when tenure is at least one
91	     * elapsed fiscal year. */
92	    default int membershipPoints(Owner owner) {
93	        int points = 0;
94	        if (hasEmail(owner)) {
95	            points += 2;
96	        }
97	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
98	            points += 1;
99	        }
100	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
101	            points += 2;
102	        }
103	        if (Tenure.fiscalYears(owner.getRegistrationDate()) >= 1) {
104	            points += 3;
105	        }
106	        return points;
107	    }
108	
109	    /** The owner's membership level from 1 to 4, derived from {@link #membershipPoints(Owner)}:
110	     * 1 for 0-1 points, 2 for 2-3, 3 for 4-5, 4 for 6 or more. */
111	    default int membershipLevel(Owner owner) {
112	        int points = membershipPoints(owner);
113	        if (points <= 1) {
114	            return 1;
115	        }
116	        if (points <= 3) {
117	            return 2;
118	        }
119	        if (points <= 5) {
120	            return 3;
121	        }
122	        return 4;
123	    }
124	
125	    /** The owner's canonical region: the REGION segment of the customer code (see
126	     * {@link CustomerCode}), or null when the customer code is unset. */
127	    default String locality(Owner owner) {
128	        return CustomerCode.region(owner.getCustomerCode());
129	    }
130	
131	    /** The owner's IANA timezone, derived from the locality/region via the pinned
132	     * region-to-timezone table (see {@link Locality#timezoneForRegion}), or null when the
133	     * region is not in the table. */
134	    default String timezone(Owner owner) {
135	        return Locality.timezoneForRegion(locality(owner));
136	    }
137	
138	    /** The owner's preferred contact channel: 'EMAIL' when an email is present, otherwise 'PHONE'. */
139	    default String contactPreference(Owner owner) {
140	        return hasEmail(owner) ? "EMAIL" : "PHONE";
141	    }
142	
143	    /** Whether the owner has a non-blank email. */
144	    private static boolean hasEmail(Owner owner) {
145	        return owner.getEmail() != null && !owner.getEmail().isBlank();
146	    }
147	
148	    /** The owner's derived identity key (see {@link OwnerIdentity}). */
149	    default String identityKey(Owner owner) {
150	        return OwnerIdentity.of(owner);
151	    }
152	
153	    /** The Luhn check digit over the digits of the owner's customer code, or null when unset. */
154	    default Integer checkDigit(Owner owner) {
155	        return owner.getCustomerCode() == null ? null : CheckDigit.luhn(owner.getCustomerCode());
156	    }
157	
158	    /** The owner's age band on their registration date, derived from their birth date (see
159	     * {@link AgeBand}), or null when either date is unset. */
160	    default String ageBand(Owner owner) {
161	        return AgeBand.on(owner.getBirthDate(), owner.getRegistrationDate());
162	    }
163	
164	    /** Whether the owner soft-matched an existing owner at creation, i.e. it has a
165	     * {@code possibleDuplicateOf} id. */
166	    default boolean possibleDuplicate(Owner owner) {
167	        return owner.getPossibleDuplicateOf() != null;
168	    }
169	
170	    @Mapping(target = "id", ignore = true)
171	    @Mapping(target = "pets", ignore = true)
172	    @Mapping(target = "customerCode", ignore = true)
173	    @Mapping(target = "householdId", ignore = true)
174	    @Mapping(target = "namesakeCount", ignore = true)
175	    @Mapping(target = "householdSize", ignore = true)
176	    @Mapping(target = "bulkSignupWarning", ignore = true)
177	    @Mapping(target = "possibleDuplicateOf", ignore = true)
178	    @Mapping(target = "deleted", ignore = true)
179	    Owner toOwner(OwnerFieldsDto ownerDto);
180	
181	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
182	
183	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
184	
185	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
186	        OwnerPageDto ownerPageDto = new OwnerPageDto();
187	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
188	        ownerPageDto.setPage(ownerPage.getNumber());
189	        ownerPageDto.setSize(ownerPage.getSize());
190	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
191	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
192	        return ownerPageDto;
193	    }
194	}
